target.css:
:root {
  --card: #fffdf7;
  --ink: #26382d;
  --muted: #6c7d70;
  --line: #d7e1d5;
  --pine: #2f6d4f;
  --pine-dark: #20513a;
  --mint: #dcefe1;
}

article.trail-card {
  box-sizing: border-box;
  width: 470px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.15;
}

.status {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--pine-dark);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.details {
  display: flex;
  gap: 8px;
  margin: 16px 0;
}

.detail {
  flex: 1;
  margin: 0;
  padding: 9px;
  border-radius: 9px;
  background: var(--mint);
}

.detail strong,
.detail span {
  display: block;
}

.detail strong {
  font-size: 14px;
}

.detail span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
}

button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 10px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--pine);
  color: var(--card);
  font-size: 13px;
  font-weight: 700;
}

button span {
  font-size: 17px;
  line-height: 0;
}

